# Fine-tune on chain_r30: working band widened to r_out = 0.30 (period 3.3 px).
#
# Why (JOURNAL 2.39): at r_out = 0.5 (Nyquist) the product frame kept only
# 0.5*r_in/0.5 of the scan band, so 20-62 % of scan energy was cut and the
# upscaled output looked soft/waxy. r_out = 0.30 keeps the band 1.67x wider
# (1.67x working pixels), so the net has to remove the residue in a domain it
# has never seen - hence this adaptation pass.
#
# Input: the dataset is generated by make_chain.py with --r-out 0.30
#   --r-out-jitter 0.05, i.e. the frame layout matches prod at r_out 0.30
#   (+-0.05 tolerance to the A0 estimate, Magazine (2) case).
#
# Start: ml/train/_chain_v1/best.pt (already chain-adapted), arch params below
#   MUST match the checkpoint (base 96, levels 3, bottleneck 3).
#
# Run: powershell -File ml/train/finetune_chain_r30.ps1

$ErrorActionPreference = "Stop"
Set-Location (Resolve-Path "$PSScriptRoot\..\..")

$env:PYTHONIOENCODING = "utf-8"
$env:PYTHONPATH = (Get-Location).Path
C:\Python314\python.exe -X utf8 -m ml.train.train `
  --data Data/chain_r30 `
  --out ml/train/_chain_r30 `
  --epochs 8 `
  --batch 2 `
  --grad-accum 2 `
  --lr 1e-5 `
  --warm-start ml/train/_chain_v1/best.pt `
  --arch-base 96 --arch-levels 3 --arch-bottleneck 3 `
  --arch-enc-blocks 1 --arch-dec-blocks 1 `
  --arch-spectral-l0 0 --arch-plain 0 --arch-spectral-mode plain `
  --ema-decay 0.999 --seed 52 `
  --cond 1 --cond-drop 0.1 --film-lr-mult 5 `
  --root-weights "chain_r30:1" `
  --val-every 1 `
  --num-workers 4 `
  --fourier-w 0.05 --lpips-w 0.05 --edge-w 0.05 --edge-alpha 2.0 --tone-w 0
